function translateNode(value: string, locale: Locale) {
  const trimmed = value.trim();
  if (!trimmed) return value;
  for (const entry of Object.values(dictionary)) {
    const source = entry.fr;
    if (trimmed === source) return value.replace(trimmed, entry[locale]);
    for (const lang of ["en", "es", "pt"] as const) {
      if (trimmed === entry[lang]) return value.replace(trimmed, entry[locale]);
    }
  }
  return value;
}

type LocaleContextValue = Preferences & { palette: Palette; setLocale: (locale: Locale) => void; setTheme: (theme: Theme) => void; setPalette: (palette: Palette) => void };
const LocaleContext = createContext<LocaleContextValue>({ ...defaults, palette: "none", setLocale: () => {}, setTheme: () => {}, setPalette: () => {} });
export function useAppPreferences() { return useContext(LocaleContext); }

export function AppPreferencesProvider({ children }: { children: ReactNode }) {
  const [preferences, setPreferences] = useState<Preferences>(defaults);
  const [palette, setPaletteState] = useState<Palette>("none");

  useEffect(() => {
    let alive = true;
    const storedLocale = localStorage.getItem("bab-locale") as Locale | null;
    const storedTheme = localStorage.getItem("bab-theme") as Theme | null;
    const storedPalette = localStorage.getItem("bab-palette") as Palette | null;
    if (storedLocale && ["fr","en","es","pt"].includes(storedLocale)) setPreferences(p => ({...p, locale:storedLocale}));
    if (storedTheme && ["light","dark"].includes(storedTheme)) setPreferences(p => ({...p, theme:storedTheme}));
    if (storedPalette && ["none","classic","crimson","azure","frost","noctis"].includes(storedPalette)) setPaletteState(storedPalette === "classic" ? "none" : storedPalette);
    (async () => {
      try {
        const supabase = getSupabaseBrowserClient() as any;
        const { data: { user } } = await supabase.auth.getUser();
        if (!user) return;
        const { data } = await supabase.from("user_settings").select("theme,preferred_language").eq("user_id", user.id).maybeSingle();
        if (alive && data) setPreferences({ locale: data.preferred_language ?? "fr", theme: data.theme ?? "light" });
      } catch {}
    })();
    return () => { alive = false; };
  }, []);

  useEffect(() => {
    document.documentElement.dataset.theme = preferences.theme;
    if (palette === "none") delete document.documentElement.dataset.palette;
    else document.documentElement.dataset.palette = palette;
    document.documentElement.lang = preferences.locale;
    localStorage.setItem("bab-locale", preferences.locale);
    localStorage.setItem("bab-theme", preferences.theme);
    localStorage.setItem("bab-palette", palette);
    let applying = false;
    const apply = () => {
      if (applying || !document.body) return;
      applying = true;
      try {
        const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
        let node: Node | null;
        while ((node = walker.nextNode())) {
          const parent = node.parentElement;
          if (!parent || parent.closest("script,style,textarea,input,[data-no-translate]")) continue;
          const currentText = node.textContent ?? "";
          const translated = translateNode(currentText, preferences.locale);
          if (translated !== currentText) node.textContent = translated;
        }
        document.body.querySelectorAll<HTMLElement>("input, textarea, select, button, a, img, [role], [title], [aria-label]").forEach(element => {
          for (const attribute of ["placeholder", "title", "aria-label", "alt"]) {
            const currentValue = element.getAttribute(attribute);
            if (!currentValue) continue;
            const translated = translateNode(currentValue, preferences.locale);
            if (translated !== currentValue) element.setAttribute(attribute, translated);
          }
        });
      } finally {
        applying = false;
      }
    };
    apply();
    // Observe newly inserted elements only. Watching characterData also observes
    // our own translations and needlessly re-enters React-managed text updates.
    const observer = new MutationObserver(() => apply());
    observer.observe(document.body, { childList:true, subtree:true, attributes:true, attributeFilter:["placeholder","title","aria-label","alt"] });
    return () => observer.disconnect();
  }, [preferences, palette]);

  const value = useMemo(() => ({
    ...preferences,
    setLocale: (locale: Locale) => setPreferences(p => ({ ...p, locale })),
    setTheme: (theme: Theme) => setPreferences(p => ({ ...p, theme })),
    palette,
    setPalette: (next: Palette) => setPaletteState(next),
  }), [preferences, palette]);

  return <LocaleContext.Provider value={value}>{children}</LocaleContext.Provider>;
}
